import re

def parse_duration(duration: str) -> int:
    if not duration:
        raise ValueError("Duration string cannot be empty")

    # Pattern to match a number followed by a unit
    pattern = r'(\d+)([hms])'
    matches = re.findall(pattern, duration)

    # Check if the entire string is consumed by the matches
    reconstructed = ''.join(num + unit for num, unit in matches)
    if reconstructed != duration:
        raise ValueError(f"Invalid duration format: {duration}")

    if not matches:
        raise ValueError(f"No valid units found in: {duration}")

    total_seconds = 0
    for num, unit in matches:
        value = int(num)
        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    return total_seconds

